"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -NoProfile -Command '$ErrorActionPreference='"'Stop'
"'$root='"'D:\\EliteSync-v10'
"'$spec=@(
@('"'EVIDENCE/APP-M5-65-INDEPENDENT-ORACLE-BUILDER-SOURCE/Build-IndependentCrlfExpected.ps1',18415,'B22FA2EDB9FBBE724E4045982BFE7D5BC4EEC3AC0EAE3C2A4ECB936E6812CC63'),
@('EVIDENCE/APP-M5-65-INDEPENDENT-ORACLE-BUILDER-SOURCE/work-review.md',3441,'5592A3F43E5745231AB54287E9CE961F2CEB4F48EA802E92EC46AB4721921DCD'))
"'$utf=[Text.UTF8Encoding]::new($false,$true)
foreach($s in $spec){
$p=Join-Path $root $s[0]
$n=Get-Item -LiteralPath $p -Force
if($n -isnot [IO.FileInfo] -or ($n.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw '"'FILE_TYPE'}
"'$d=$n.Directory
while($null -ne $d){if($d -isnot [IO.DirectoryInfo] -or ($d.Attributes -band [IO.FileAttributes]::ReparsePoint)){throw '"'ANCESTOR_TYPE'};"'$d=$d.Parent}
$b=[IO.File]::ReadAllBytes($p)
$sha=[Security.Cryptography.SHA256]::Create()
try{$h=[BitConverter]::ToString($sha.ComputeHash($b)).Replace('"'-','')}finally{"'$sha.Dispose()}
if($b.Length -ne $s[1] -or $h -cne $s[2]){throw '"'IDENTITY'}
"'$t=$utf.GetString($b)
[ordered]@{Path=$s[0];Bytes=$b.Length;SHA256=$h;FullAncestorNonReparse=$true}|ConvertTo-Json -Compress
$t
}'
